const pg = $input.first().json;
const body = $('Webhook - Handoff Trigger').first().json.body || {};
const requestedConvId = pg.requested_conv_id || body.conv_id || null;

if (!pg.conv_id) {
  return [{ json: {
    conv_id: null,
    requested_conv_id: requestedConvId,
    has_conv: false,
    not_ready_reason: 'conversation_not_found',
    response_code: 404,
    response_message: 'Conversation not found for provided conv_id.',
    chatwoot_conv_id: null,
    estado: null,
    note_body: null,
    resumen_ia: '',
    plan_interes: '',
    nivel_interes: 'ALTO',
    evento_payload: '{}'
  }}];
}

if (pg.estado === 'HANDOFF_HUMAN') {
  return [{ json: {
    conv_id: pg.conv_id,
    requested_conv_id: requestedConvId,
    chatwoot_conv_id: pg.chatwoot_conv_id,
    has_conv: false,
    not_ready_reason: 'already_transferred',
    response_code: 409,
    response_message: 'Conversation is already transferred to a human agent.',
    estado: pg.estado,
    note_body: null,
    resumen_ia: '',
    plan_interes: '',
    nivel_interes: 'ALTO',
    evento_payload: '{}'
  }}];
}

const resumen = body.resumen ||
  `Cliente interesado en ${pg.marca || ''} ${pg.modelo || ''}. Solicita hablar con asesor.`;
const planInteres = body.plan_interes || pg.plan_interes || '';

const VALID_NIVELES = ['ALTO', 'MEDIO', 'BAJO'];
const nivelInteres = VALID_NIVELES.includes(body.nivel_interes) ? body.nivel_interes : 'ALTO';

const noteContent = [
  '🤝 *Handoff — Agente IA CRIS*',
  '',
  `*Cliente:* ${pg.nombre || 'Prospecto'}`,
  `*Teléfono:* ${pg.telefono || ''}`,
  `*Vehículo:* ${[pg.marca, pg.modelo].filter(Boolean).join(' ')}`,
  `*Estado CRIS:* ${pg.estado || ''}`,
  `*Nivel de interés:* ${nivelInteres}`,
  `*Plan de interés:* ${planInteres || '—'}`,
  `*QuickLink ID:* ${pg.quicklink_id || ''}`,
  '',
  '*Resumen IA:*',
  resumen,
  '',
  '⚡ _Acción: Contactar al cliente para cerrar la venta._'
].join('\n');

const noteBody = JSON.stringify({
  content: noteContent,
  message_type: 'outgoing',
  private: true
});

const eventoPayload = JSON.stringify({
  chatwoot_conv_id: pg.chatwoot_conv_id,
  chatwoot_contact_id: pg.chatwoot_contact_id,
  nivel_interes: nivelInteres,
  plan_interes: planInteres
});

const hasChatwoot = !!(pg.chatwoot_conv_id && pg.chatwoot_contact_id);
return [{ json: {
  conv_id: pg.conv_id,
  requested_conv_id: requestedConvId,
  nombre: pg.nombre || 'Prospecto',
  telefono: pg.telefono,
  marca: pg.marca,
  modelo: pg.modelo,
  estado: pg.estado,
  quicklink_id: pg.quicklink_id,
  chatwoot_conv_id: pg.chatwoot_conv_id,
  chatwoot_contact_id: pg.chatwoot_contact_id,
  has_conv: hasChatwoot,
  not_ready_reason: hasChatwoot ? null : 'chatwoot_not_synced',
  response_code: hasChatwoot ? 200 : 202,
  response_message: hasChatwoot ? 'Handoff ready.' : 'Chatwoot not yet synced. Retry in 5 minutes.',
  note_body: noteBody,
  resumen_ia: resumen,
  plan_interes: planInteres,
  nivel_interes: nivelInteres,
  evento_payload: eventoPayload
}}];

const item = $input.first().json || {};
if (!item.conv_id || !item.chatwoot_conv_id) {
  return [];
}
const mensajes = Array.isArray(item.mensajes) ? item.mensajes : [];

const lines = [
  '🤖 *CRIS — Contexto del Lead*',
  '',
  `*Cliente:* ${item.nombre || 'Prospecto'}`,
  `*Teléfono:* ${item.telefono || ''}`,
  `*Vehículo:* ${[item.marca, item.modelo].filter(Boolean).join(' ')}`,
  `*Estado CRIS:* ${item.estado || ''}`,
  `*QuickLink ID:* ${item.quicklink_id || ''}`,
];

if (mensajes.length > 0) {
  lines.push('');
  lines.push(`*Historial de mensajes (${mensajes.length}):*`);
  mensajes.forEach(m => {
    const ts = m.created_at
      ? new Date(m.created_at).toLocaleString('es-EC', {day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})
      : '';
    const dir = m.direccion === 'inbound' ? '← Lead' : '→ CRIS';
    const texto = (m.contenido_msg || '').substring(0, 200);
    lines.push(`[${ts}] ${dir}: ${texto}`);
  });
}

lines.push('');
lines.push('_Sincronizado automáticamente desde el agente CRIS._');

const noteContent = lines.join('\n');

const noteBody = JSON.stringify({
  content: noteContent,
  message_type: 'outgoing',
  private: true
});

const eventoPayload = JSON.stringify({
  chatwoot_conv_id: item.chatwoot_conv_id,
  mensajes_incluidos: mensajes.length
}).replace(/'/g, "''");

return [{
  json: {
    conv_id: item.conv_id,
    chatwoot_conv_id: item.chatwoot_conv_id,
    note_body: noteBody,
    evento_payload: eventoPayload
  }
}];
